/// The nickname if there is one that is not empty, otherwise the real name.
fn display_name(nickname: &Option<String>, real: &str) -> String {
    nickname
        .as_deref()
        .filter(|n| !n.is_empty())
        .unwrap_or(real)
        .to_string()
}

